import { NextRequest, NextResponse } from 'next/server';
import { getAuthUser } from '@/lib/utils/auth.utils';
import sharp from 'sharp';
import path from 'path';
import { writeFile } from 'fs/promises';

export async function POST(req: NextRequest) {
  // 1. Verificamos que el usuario esté logueado
  const { user } = getAuthUser(req);
  if (!user) {
    return NextResponse.json({ message: 'No autorizado' }, { status: 401 });
  }

  try {
    // 2. Extraemos el archivo del FormData
    const formData = await req.formData();
    const file = formData.get('avatar') as File;

    if (!file) {
      return NextResponse.json({ message: 'No se envió ninguna imagen' }, { status: 400 });
    }

    // 3. Convertimos el archivo a un Buffer que 'sharp' pueda leer
    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);

    // 4. Definimos el nombre del archivo (usamos el ID del usuario para que sea único)
    const filename = `${user.id}-${Date.now()}.webp`;
    
    // Ruta absoluta donde se guardará (en la carpeta public/avatars)
    const filepath = path.join(process.cwd(), 'public', 'avatars', filename);

    // 5. MAGIA DE SHARP: Redimensionamos a 500x500 y convertimos a WebP
    await sharp(buffer)
      .resize(500, 500, { fit: 'cover' }) // Recorta la imagen para que sea un cuadrado perfecto
      .webp({ quality: 80 }) // 80% de calidad es excelente para webp y pesa poquísimo
      .toFile(filepath);

    // 6. Devolvemos la URL pública con la que el frontend podrá ver la imagen
    const publicUrl = `/avatars/${filename}`;

    return NextResponse.json({ 
      success: true, 
      url: publicUrl 
    });

  } catch (error) {
    console.error('Error procesando la imagen:', error);
    return NextResponse.json({ message: 'Error al procesar la imagen' }, { status: 500 });
  }
}